#!/usr/bin/env bash
# TOGA2 (upstream early-access) on Tier 3 (deep aculeate homology).
#
# Reuses chain files generated by `run_toga_tier3.sh` (the TOGA1 run): both
# tools consume the same make_lastz_chains output, so this script only adds
# the TOGA2-specific projection step on top.
#
# *** Run `bash scripts/benchmark/run_toga_tier3.sh` FIRST. ***
#
# That script generates:
#   benchmark_results/toga/work/2bit/Apis_mellifera.2bit
#   benchmark_results/toga/work/2bit/<species>.2bit
#   benchmark_results/toga/work/chains/Apis_mellifera.<species>.final.chain.gz
#   benchmark_results/toga/work/bed/Apis_mellifera.melittin.bed12
# This script picks those up and runs TOGA2 against them.
#
# WHY TOGA2 OUTPUT IS PARSED HEURISTICALLY:
#   TOGA2 is upstream-current but docs are incomplete (early access). The
#   orthology output filename is not formally documented; we glob the project
#   directory for a TSV with classification labels. If your TOGA2 build
#   produces a different filename, edit `parse_outputs` below.
#
# WHERE TO RUN: ≥22 GB RAM PC (same as TOGA1).
#
# Usage:
#   bash scripts/benchmark/toga_setup.sh                 # one-time install
#   bash scripts/benchmark/run_toga_tier3.sh             # TOGA1 (generates chains)
#   bash scripts/benchmark/run_toga2_tier3.sh            # TOGA2 (reuses chains)

set -uo pipefail

# ── paths ────────────────────────────────────────────────────────────────
REPO="${REPO:-/home/faw/dev/projects/SynVoy}"
# By default reuse the same work tree as TOGA1 so chains/2bits are shared.
TOGA1_WORK="${TOGA1_WORK:-${REPO}/benchmark_results/toga/work}"
OUTDIR="${OUTDIR:-${REPO}/benchmark_results/toga2}"
WORK="${OUTDIR}/work"

TIER3_SPECIES=(
    Tetramorium_bicarinatum
    Cardiocondyla_obscurior
    Formica_selysi
    Vespa_velutina
    Polistes_canadensis
    Solenopsis_invicta
    Vollenhovia_emeryi
)

THREADS="${THREADS:-4}"
TOGA2_ENV="${TOGA2_ENV:-synvoy_toga2}"
TOOLS_DIR="${TOOLS_DIR:-${HOME}/dev/tools}"
TOGA2_PY="${TOGA2_PY:-${TOOLS_DIR}/TOGA2/toga2.py}"

# To run a subset:
#   ONLY=Cardiocondyla_obscurior bash run_toga2_tier3.sh
ONLY="${ONLY:-}"

mkdir -p "${WORK}/{logs,toga2_runs}"
mkdir -p "${WORK}/logs" "${WORK}/toga2_runs"

# ── stage 1: verify env + TOGA1 outputs ─────────────────────────────────
setup_envs() {
    echo "=== [stage 1] verify TOGA2 env + TOGA1 chains ==="
    if ! mamba env list 2>/dev/null | grep -qE "^\s*${TOGA2_ENV}(\s|$)"; then
        echo "  ERROR: conda env '${TOGA2_ENV}' not found." >&2
        echo "  Run scripts/benchmark/toga_setup.sh first." >&2
        return 1
    fi
    if [[ ! -f "${TOGA2_PY}" ]]; then
        echo "  ERROR: TOGA2 toga2.py not at ${TOGA2_PY}" >&2
        echo "  Run scripts/benchmark/toga_setup.sh first." >&2
        return 1
    fi

    local apis_2bit="${TOGA1_WORK}/2bit/Apis_mellifera.2bit"
    local apis_bed="${TOGA1_WORK}/bed/Apis_mellifera.melittin.bed12"
    if [[ ! -s "${apis_2bit}" || ! -s "${apis_bed}" ]]; then
        echo "  ERROR: TOGA1 reference inputs missing under ${TOGA1_WORK}." >&2
        echo "  Run scripts/benchmark/run_toga_tier3.sh first to generate them." >&2
        echo "    expected: ${apis_2bit}" >&2
        echo "    expected: ${apis_bed}" >&2
        return 1
    fi
    echo "  env: ${TOGA2_ENV}"
    echo "  TOGA2 toga2.py: ${TOGA2_PY}"
    echo "  reusing TOGA1 work tree: ${TOGA1_WORK}"
}

# ── stage 2: run TOGA2 per target ────────────────────────────────────────
run_target() {
    local sp="$1"
    local target_2bit="${TOGA1_WORK}/2bit/${sp}.2bit"
    local chain_file="${TOGA1_WORK}/chains/Apis_mellifera.${sp}.final.chain.gz"
    local apis_2bit="${TOGA1_WORK}/2bit/Apis_mellifera.2bit"
    local apis_bed="${TOGA1_WORK}/bed/Apis_mellifera.melittin.bed12"
    local toga2_out="${WORK}/toga2_runs/${sp}"

    if [[ ! -s "${chain_file}" ]]; then
        echo "  [${sp}] no chain file (TOGA1 didn't produce one), skipping"
        return 0
    fi
    if [[ ! -s "${target_2bit}" ]]; then
        echo "  [${sp}] no target 2bit, skipping"
        return 0
    fi

    # Idempotency: if any TSV with TOGA2 class labels exists under toga2_out,
    # assume the run finished and skip.
    if [[ -d "${toga2_out}" ]] && find "${toga2_out}" -maxdepth 3 -name '*.tsv' -size +0c 2>/dev/null | head -1 | grep -q .; then
        echo "  [${sp}] TOGA2 output already present, skipping"
        return 0
    fi

    mkdir -p "${toga2_out}"
    echo "  [${sp}] running TOGA2 (orthology projection)"

    # TOGA2 'run' subcommand (per upstream wiki, early-access docs):
    #   --ref_2bit / --query_2bit / --chain_file / --ref_annotation
    #   --no_isoform_file / --no_u12_file / --no_spliceai  → skip semi-mandatory inputs
    #   --output / --project_name
    #   --parallel_strategy local
    # If the flag names drift, update here. The mamba run will surface
    # `Error: No such option:` from click immediately.
    mamba run -n "${TOGA2_ENV}" python3 "${TOGA2_PY}" run \
        --ref_2bit "${apis_2bit}" \
        --query_2bit "${target_2bit}" \
        --chain_file "${chain_file}" \
        --ref_annotation "${apis_bed}" \
        --no_isoform_file \
        --no_u12_file \
        --no_spliceai \
        --output "${toga2_out}" \
        --project_name "${sp}" \
        --parallel_strategy local \
        > "${WORK}/logs/${sp}_toga2.log" 2>&1 \
        || { echo "    TOGA2 FAILED — see ${WORK}/logs/${sp}_toga2.log"; return 1; }

    echo "  [${sp}] DONE"
}

# ── stage 3: parse TOGA2 outputs into normalized calls.tsv ───────────────
parse_outputs() {
    echo "=== [stage 3] parse TOGA2 outputs into calls.tsv ==="
    local calls="${OUTDIR}/calls.tsv"
    printf "species\taccession\tcalled_status\tlocus_chrom\tlocus_start\tlocus_end\tstrand\tconfidence\textra\n" > "${calls}"

    # Heuristic parser: TOGA2 docs don't pin down the orthology TSV filename.
    # Search the per-species project dir for a TSV containing TOGA-style class
    # labels (one2one / one2many / many2one / many2many / one2zero) and pick
    # the gene-Melt row.
    for sp in "${TIER3_SPECIES[@]}"; do
        local toga2_out="${WORK}/toga2_runs/${sp}"
        if [[ ! -d "${toga2_out}" ]]; then
            printf "%s\t-\tABSENT\t-\t-\t-\t-\t-\ttoga2_no_run_dir\n" "${sp}" >> "${calls}"
            continue
        fi
        local class_tsv
        class_tsv=$(grep -rlE "one2(one|many|zero)|many2(one|many)" "${toga2_out}" --include='*.tsv' 2>/dev/null | head -1)
        if [[ -z "${class_tsv}" ]]; then
            printf "%s\t-\tABSENT\t-\t-\t-\t-\t-\ttoga2_no_classification_tsv\n" "${sp}" >> "${calls}"
            continue
        fi
        local row
        row=$(grep -E "gene-Melt|Melt" "${class_tsv}" 2>/dev/null | head -1)
        if [[ -z "${row}" ]]; then
            printf "%s\t-\tABSENT\t-\t-\t-\t-\t-\ttoga2_no_melittin_in=%s\n" "${sp}" "$(basename "${class_tsv}")" >> "${calls}"
            continue
        fi
        local class_label
        class_label=$(awk -F'\t' '{for(i=1;i<=NF;i++) if($i~/^one2(one|many|zero)$|^many2(one|many)$/){print $i; exit}}' <<<"${row}")
        local status
        case "${class_label}" in
            one2zero|"") status="ABSENT" ;;
            *) status="PRESENT" ;;
        esac
        printf "%s\t-\t%s\t-\t-\t-\t-\t%s\ttoga2_class=%s;src=%s\n" \
            "${sp}" "${status}" "${class_label:--}" "${class_label:--}" "$(basename "${class_tsv}")" >> "${calls}"
    done

    echo "  wrote ${calls}"
    awk -F'\t' 'NR>1 {print $3}' "${calls}" | sort | uniq -c
}

# ── orchestration ────────────────────────────────────────────────────────
echo "=== TOGA2-Tier3 benchmark on $(hostname) at $(date -Iseconds) ==="
echo "Memory:  $(free -h | awk '/^Mem:/{print $2}') total, $(nproc) CPUs"
echo

setup_envs        || { echo "STAGE 1 FAILED"; exit 1; }

echo "=== [stage 2] per-target TOGA2 runs ==="
if [[ -n "${ONLY}" ]]; then
    declare -A keep
    for sp in ${ONLY}; do keep[$sp]=1; done
    SPECIES_TO_RUN=()
    for sp in "${TIER3_SPECIES[@]}"; do
        [[ -n "${keep[$sp]:-}" ]] && SPECIES_TO_RUN+=("$sp")
    done
    echo "  ONLY filter active — running: ${SPECIES_TO_RUN[*]}"
else
    SPECIES_TO_RUN=("${TIER3_SPECIES[@]}")
fi

for sp in "${SPECIES_TO_RUN[@]}"; do
    run_target "${sp}" || echo "  [${sp}] failed (continuing)"
done

parse_outputs
echo
echo "Done. calls.tsv: ${OUTDIR}/calls.tsv"
